/// An assembled covariance (root.assemble_covariance), OWNED: copies
/// share it, the last copy releases it, and later assemblies are
/// independent. Entity arguments must come from the live model.
class Covariance {
public:
    Covariance() : c_(nullptr) {}
    explicit Covariance(ffi::BaGraphCov* c)
        : c_(c), guard_(c, ffi::ba_graph_cov_free) {}
    /// Error text of the last failed query on this assembly.
    const char* last_error() const { return ffi::ba_graph_cov_error(c_); }
    /// What the assembly decided -- the ordering it kept, what the
    /// candidates priced at, and how many symbolics it built.
    CovPlan plan() const {
        CovPlan p;
        ffi::ba_graph_cov_plan(c_, &p);
        return p;
    }
    /// Per-parameter standard deviations into out; returns the count
    /// or a negative code. Works on every CovMode incl. TriDiagonal.
    int32_t std_dev(const BaCam& e, double* out, uint32_t cap) {
        return ck_(ffi::ba_graph_ba_cam_std_dev(c_, e.raw(), out, cap));
    }
    /// Row-major dim x dim conditional covariance (all other
    /// parameters held fixed) into out; returns dim or a negative code.
    int32_t conditional(const BaCam& e, double* out, uint32_t cap) {
        return ck_(ffi::ba_graph_ba_cam_conditional_cov(c_, e.raw(), out, cap));
    }
    /// Row-major dim x dim into out; returns dim or a negative code.
    int32_t marginal(const BaCam& e, double* out, uint32_t cap) {
        return ck_(ffi::ba_graph_ba_cam_marginal_cov(c_, e.raw(), out, cap));
    }
    /// Per-parameter standard deviations into out; returns the count
    /// or a negative code. Works on every CovMode incl. TriDiagonal.
    int32_t std_dev(const BaPoint& e, double* out, uint32_t cap) {
        return ck_(ffi::ba_graph_ba_point_std_dev(c_, e.raw(), out, cap));
    }
    /// Row-major dim x dim conditional covariance (all other
    /// parameters held fixed) into out; returns dim or a negative code.
    int32_t conditional(const BaPoint& e, double* out, uint32_t cap) {
        return ck_(ffi::ba_graph_ba_point_conditional_cov(c_, e.raw(), out, cap));
    }
    result<matrix3d, CovError> marginal(const BaPoint& e) {
        double b[9];
        if (ck_(ffi::ba_graph_ba_point_marginal_cov(c_, e.raw(), b, 9)) < 0) return fail<matrix3d>();
        return result<matrix3d, CovError>::ok(matrix3d::from_elements(
            b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7], b[8]));
    }
    /// Row-major BaCam::param_count x BaCam::param_count cross-covariance
    /// into out; returns the row count or a negative code.
    int32_t cross(const BaCam& a, const BaCam& b, double* out, uint32_t cap) {
        return ck_(ffi::ba_graph_ba_cam_ba_cam_cross_cov(c_, a.raw(), b.raw(), out, cap));
    }
    /// Row-major BaCam::param_count x BaPoint::param_count cross-covariance
    /// into out; returns the row count or a negative code.
    int32_t cross(const BaCam& a, const BaPoint& b, double* out, uint32_t cap) {
        return ck_(ffi::ba_graph_ba_cam_ba_point_cross_cov(c_, a.raw(), b.raw(), out, cap));
    }
    /// Row-major BaPoint::param_count x BaCam::param_count cross-covariance
    /// into out; returns the row count or a negative code.
    int32_t cross(const BaPoint& a, const BaCam& b, double* out, uint32_t cap) {
        return ck_(ffi::ba_graph_ba_point_ba_cam_cross_cov(c_, a.raw(), b.raw(), out, cap));
    }
    /// Row-major BaPoint::param_count x BaPoint::param_count cross-covariance
    /// into out; returns the row count or a negative code.
    int32_t cross(const BaPoint& a, const BaPoint& b, double* out, uint32_t cap) {
        return ck_(ffi::ba_graph_ba_point_ba_point_cross_cov(c_, a.raw(), b.raw(), out, cap));
    }
private:
    /// A caught Rust panic (-2) throws; other codes pass through.
    int32_t ck_(int32_t n) const {
        if (n == -2) throw PanicError(ffi::ba_graph_cov_error(c_));
        return n;
    }
    template<class T> result<T, CovError> fail() {
        return result<T, CovError>::err({ffi::ba_graph_cov_error(c_)});
    }
    ffi::BaGraphCov* c_;
    std::shared_ptr<void> guard_;
};

inline result<Covariance, CovError> LmResult::covariance() const {
    ffi::BaGraphCov* c = nullptr;
    int32_t code = detail ? ffi::ba_graph_result_covariance(detail, &c) : 1;
    if (code == 0)
        return result<Covariance, CovError>::ok(Covariance(c));
    if (code == 1)
        return result<Covariance, CovError>::err({"no covariance: the config did not ask for one"});
    if (code == 2)
        return result<Covariance, CovError>::err({"no covariance: an earlier covariance() call took it"});
    return result<Covariance, CovError>::err({ffi::ba_graph_result_error(detail)});
}

/// `BaGraph.cams`. Element pointers are STABLE across pushes (chunked storage).
class BaGraphCamsVec {
public:
    explicit BaGraphCamsVec(ffi::BaGraph* h) : h_(h) {}
    uint32_t size() const { return ffi::ba_graph_cams_len(h_); }
    bool empty() const { return size() == 0; }
    void reserve(uint32_t additional) { ffi::ba_graph_cams_reserve(h_, additional); }
    /// Appends a default element and returns a wrapper for it.
    ///
    /// The wrapper holds a pointer INTO the collection, so it follows the
    /// std::vector rule: any later push may reallocate, and every wrapper
    /// taken before it -- including wrappers into collections nested inside
    /// these elements -- is then dangling. Either reserve() the count up
    /// front, or re-take the wrapper with operator[] after the growth.
    /// To hold on to an element across pushes, keep its Ref, not a wrapper.
    BaCam push() { return BaCam(ffi::ba_graph_cams_push(h_)); }
    /// Wrapper for element `i`; see push() on how long it stays valid.
    BaCam operator[](uint32_t i) { return BaCam(ffi::ba_graph_cams_at(h_, i)); }
    /// Front/back of a non-empty vec (empty = UB, like STL).
    BaCam front() { return (*this)[0]; }
    BaCam back() { return (*this)[size() - 1]; }
    /// Drops the last element; false when already empty.
    bool pop() { return ffi::ba_graph_cams_pop(h_); }
    void clear() { ffi::ba_graph_cams_clear(h_); }
    void truncate(uint32_t n) { ffi::ba_graph_cams_truncate(h_, n); }
    BaCamRef ref_at(uint32_t i) const { return BaCamRef{ffi::ba_graph_cams_ref_at(h_, i)}; }
    /// Ref of the first/last element; null when empty.
    BaCamRef first_ref() const { return BaCamRef{ffi::ba_graph_cams_first_ref(h_)}; }
    BaCamRef last_ref() const { return BaCamRef{ffi::ba_graph_cams_last_ref(h_)}; }
    BaCam get(BaCamRef r) { return BaCam(ffi::ba_graph_cams_get(h_, r.raw)); }
    /// True while r addresses a live element here.
    bool contains(BaCamRef r) const { return ffi::ba_graph_cams_contains(h_, r.raw); }
    /// Like get, but empty for a stale or foreign ref.
    option<BaCam> try_get(BaCamRef r) {
        ffi::BaCam* p = ffi::ba_graph_cams_try_get(h_, r.raw);
        return p ? option<BaCam>(BaCam(p)) : option<BaCam>();
    }
    /// Bidirectional iterator. Standard C++ contract: modifying the
    /// container while iterating is undefined behavior. Dereference
    /// yields a value wrapper (BaCam), like vector<bool> --
    /// reference is a value type.
    class iterator {
    public:
        using iterator_category = std::bidirectional_iterator_tag;
        using value_type = BaCam;
        using difference_type = std::ptrdiff_t;
        using reference = BaCam;
        struct arrow { BaCam v; BaCam* operator->() { return &v; } };
        using pointer = arrow;

        iterator() : h_(nullptr), i_(0) {}
        iterator(ffi::BaGraph* h, uint32_t i) : h_(h), i_(i) {}
        BaCam operator*() const { return BaCam(ffi::ba_graph_cams_at(h_, i_)); }
        arrow operator->() const { return arrow{**this}; }
        iterator& operator++() { ++i_; return *this; }
        iterator& operator--() { --i_; return *this; }
        iterator operator++(int) { iterator t = *this; ++*this; return t; }
        iterator operator--(int) { iterator t = *this; --*this; return t; }
        bool operator==(const iterator& o) const { return i_ == o.i_; }
        bool operator!=(const iterator& o) const { return i_ != o.i_; }
    private:
        ffi::BaGraph* h_;
        uint32_t i_;
    };
    iterator begin() { return iterator(h_, 0); }
    iterator end() { return iterator(h_, size()); }
    class reverse_iterator {
    public:
        using iterator_category = std::bidirectional_iterator_tag;
        using value_type = BaCam;
        using difference_type = std::ptrdiff_t;
        using reference = BaCam;
        using pointer = iterator::arrow;

        reverse_iterator() {}
        explicit reverse_iterator(iterator base) : base_(base) {}
        iterator base() const { return base_; }
        BaCam operator*() const { iterator t = base_; --t; return *t; }
        pointer operator->() const { return pointer{**this}; }
        reverse_iterator& operator++() { --base_; return *this; }
        reverse_iterator& operator--() { ++base_; return *this; }
        reverse_iterator operator++(int) { reverse_iterator t = *this; ++*this; return t; }
        reverse_iterator operator--(int) { reverse_iterator t = *this; --*this; return t; }
        bool operator==(const reverse_iterator& o) const { return base_ == o.base_; }
        bool operator!=(const reverse_iterator& o) const { return base_ != o.base_; }
    private:
        iterator base_;
    };
    reverse_iterator rbegin() { return reverse_iterator(end()); }
    reverse_iterator rend() { return reverse_iterator(begin()); }
private:
    ffi::BaGraph* h_;
};

